profit='def estimate(kind, count):\n    if kind == "small":\n        sale, days, material = 220000, 17, 100000\n    else:\n        sale, days, material = 400000, 23, 190000\n    revenue = sale * count\n    labour = days * count * 2500\n    materials = material * count\n    return revenue - 500000 - labour - materials'
