stackremove='def remove_target(stack, target, make_stack):\n    temp = make_stack()\n    removed = None\n    while not stack.isEmpty():\n        item = stack.pop()\n        if item.identifier == target:\n            removed = item\n            break\n        temp.push(item)\n    while not temp.isEmpty():\n        stack.push(temp.pop())\n    return removed'
